def pluck(arr):
    if not arr:
        return []

    even_nodes = [(node, index) for index, node in enumerate(arr) if node % 2 == 0]

    if not even_nodes:
        return []

    smallest_even_node = min(even_nodes, key=lambda x: (x[0], x[1]))

    return [smallest_even_node[0], smallest_even_node[1]]
